import ("context";"testing")
func TestEvalCaseContextCancelParentTree2(t *testing.T) {
root,cancel:=context.WithCancel(context.Background());defer cancel();ctx:=root
    for i:=0;i<7;i++{next,stop:=context.WithCancel(ctx);defer stop();ctx=next};cancel()
    if e:=WaitForCancel(ctx);e!=context.Canceled{t.Fatal(e)}
}
